query:
mutation CreateCart($input: CreateCartInput!) {
  cart {
    createCart(input: $input) {
      cart {
        ...CartDetail
      }
    }
  }
}

fragment CartDetail on Cart {
  entityId
  currencyCode
  isTaxIncluded
  baseAmount {
    value
    currencyCode
  }
  discountedAmount {
    value
    currencyCode
  }
  amount {
    value
    currencyCode
  }
  discounts {
    entityId
    discountedAmount {
      value
      currencyCode
    }
  }
  createdAt {
    utc
  }
  updatedAt {
    utc
  }
  locale
  version
  lineItems {
    totalQuantity
    physicalItems {
      entityId
      parentEntityId
      productEntityId
      variantEntityId
      sku
      name
      path
      brand
      quantity
      isTaxable
      isMutable
      isShippingRequired
      image {
        url(width: 320)
        altText
      }
      selectedOptions {
        __typename
        entityId
        name
        ... on CartSelectedMultipleChoiceOption {
          value
          valueEntityId
        }
      }
      listPrice {
        value
        currencyCode
      }
      originalPrice {
        value
        currencyCode
      }
      salePrice {
        value
        currencyCode
      }
      extendedListPrice {
        value
        currencyCode
      }
      extendedSalePrice {
        value
        currencyCode
      }
      discountedAmount {
        value
        currencyCode
      }
      couponAmount {
        value
        currencyCode
      }
      discounts {
        entityId
        discountedAmount {
          value
          currencyCode
        }
      }
    }
    digitalItems {
      entityId
      parentEntityId
      productEntityId
      variantEntityId
      sku
      name
      path
      brand
      quantity
      isTaxable
      isMutable
      image {
        url(width: 320)
        altText
      }
      selectedOptions {
        __typename
        entityId
        name
      }
      listPrice {
        value
        currencyCode
      }
      originalPrice {
        value
        currencyCode
      }
      salePrice {
        value
        currencyCode
      }
      extendedListPrice {
        value
        currencyCode
      }
      extendedSalePrice {
        value
        currencyCode
      }
      discountedAmount {
        value
        currencyCode
      }
      couponAmount {
        value
        currencyCode
      }
    }
    giftCertificates {
      entityId
      name
      amount {
        value
        currencyCode
      }
    }
    customItems {
      entityId
      sku
      name
      quantity
      listPrice {
        value
        currencyCode
      }
    }
  }
}
